def safe_count(limit):
    if not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a non-negative integer')
    count = 0
    max_iterations = limit * 2 + 1
    while count < limit:
        print('count =', count)
        count = count + 1
        if count > max_iterations:
            raise RuntimeError('iteration safeguard triggered')

if __name__ == '__main__':
    try:
        user_limit = int(input('Enter limit: '))
        safe_count(user_limit)
    except ValueError as ve:
        print('Invalid input:', ve)
    except RuntimeError as re:
        print('Safety error:', re)

