import time

def read_sensor():
    # Simulated sensor for demonstration
    import random
    return random.choice([22.5, None, 23.0, None, 21.8])

readings = 0
consecutive_none = 0
max_readings = 10
max_none_count = 30

while True:
    temp = read_sensor()
    if temp is None:
        consecutive_none += 1
    else:
        consecutive_none = 0
        readings += 1
        print('Temperature:', temp)
    if readings >= max_readings:
        break
    if consecutive_none >= max_none_count:
        print('Sensor fault detected. Stopping.')
        break
    time.sleep(1)

