        yield v

def consume_generator(gen):
    try:
        item = next(gen)
    except StopIteration:
        print('Generator exhausted')
        return
    while True:
        try:
            print(item)
            item = next(gen)
        except StopIteration:
            print('Generator exhausted')
            break
